export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.22, 0.2, 0.44);
  scene.useRightHandedSystem = true;

  const alphaThres = 1.3;
  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0, 1.5, 0));
  camera.alpha = 1.8;
  camera.lowerAlphaLimit = camera.alpha - alphaThres;
  camera.upperAlphaLimit = camera.alpha + alphaThres;
  camera.beta = 1.6;
  camera.lowerBetaLimit = camera.beta - alphaThres;
  camera.upperBetaLimit = camera.beta + alphaThres;
  camera.radius = 5.14;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 1000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const root = new BABYLON.TransformNode("root", scene);
  root.rotationQuaternion = new BABYLON.Quaternion();

  const scaleFactor = 1.5;

  var ground = BABYLON.MeshBuilder.CreateBox("ground", { width: scaleFactor * 100, depth: scaleFactor * 100, height: 0.001 }, scene); // size should be big enough to hideall you wan
  ground.rotation.x = -Math.PI / 2;

  var skyBox = BABYLON.MeshBuilder.CreateBox("SkyBox", { size: scaleFactor * 15, sideOrientation: BABYLON.Mesh.BACKSIDE }, scene);
  skyBox.material = new BABYLON.SkyMaterial("sky", scene);
  skyBox.material.inclination = -0.15;
  skyBox.renderingGroupId = 1;
  skyBox.position.z = (-scaleFactor * 15) / 2 - 0.1;

  var hole = BABYLON.MeshBuilder.CreateBox("hole", { width: scaleFactor, height: scaleFactor * 2 }, scene);

  var groundCSG = BABYLON.CSG.FromMesh(ground);
  var holeCSG = BABYLON.CSG.FromMesh(hole);
  var booleanCSG = groundCSG.subtract(holeCSG);
  var occluder = booleanCSG.toMesh("occluder", null, scene);
  occluder.renderingGroupId = 0;

  const backgroundColor = scene.clearColor;
  const occluderMaterial = new BABYLON.StandardMaterial("occluderMat", scene);
  occluderMaterial.diffuseColor = new BABYLON.Color3(backgroundColor.r, backgroundColor.g, backgroundColor.b);
  occluderMaterial.emissiveColor = new BABYLON.Color3(backgroundColor.r, backgroundColor.g, backgroundColor.b);
  occluderMaterial.specularColor = new BABYLON.Color3(0, 0, 0);
  occluderMaterial.disableLighting = true;
  occluder.material = occluderMaterial;

  ground.dispose();
  hole.dispose();

  scene.setRenderingAutoClearDepthStencil(1, false, false, false); // Do not clean buffer info to ensure occlusion
  scene.setRenderingAutoClearDepthStencil(0, true, true, true); // Clean for 1rst frame
  scene.autoClear = true;

  occluder.parent = root;
  root.position.y = scaleFactor;

  function createExtrudeFrame() {
    const width = scaleFactor * 1.1;
    const depth = scaleFactor * 2.1;
    const radius = 0.26;
    const dTheta = Math.PI / 40;

    function createRoundedShape(w, d, r) {
      const points = [];
      let centerX = -(0.5 * w - r);
      let centerZ = -(0.5 * d - r);
      for (let theta = Math.PI; theta <= 1.5 * Math.PI; theta += dTheta) {
        points.push(new BABYLON.Vector3(centerX + r * Math.cos(theta), 0, centerZ + r * Math.sin(theta)));
      }
      centerX = 0.5 * w - r;
      for (let theta = 1.5 * Math.PI; theta <= 2 * Math.PI; theta += dTheta) {
        points.push(new BABYLON.Vector3(centerX + r * Math.cos(theta), 0, centerZ + r * Math.sin(theta)));
      }
      centerZ = 0.5 * d - r;
      for (let theta = 0; theta <= 0.5 * Math.PI; theta += dTheta) {
        points.push(new BABYLON.Vector3(centerX + r * Math.cos(theta), 0, centerZ + r * Math.sin(theta)));
      }
      centerX = -(0.5 * w - r);
      for (let theta = 0.5 * Math.PI; theta <= Math.PI; theta += dTheta) {
        points.push(new BABYLON.Vector3(centerX + r * Math.cos(theta), 0, centerZ + r * Math.sin(theta)));
      }
      return points;
    }

    const outerShape = createRoundedShape(width, depth, radius);
    const borderThickness = 0.1;
    const innerShape = createRoundedShape(width - borderThickness * 2, depth - borderThickness * 2, radius - borderThickness);

    const outerPolygon = BABYLON.MeshBuilder.ExtrudePolygon(
      "outerPolygon",
      {
        shape: outerShape,
        depth: 0.1,
        sideOrientation: BABYLON.Mesh.DOUBLESIDE,
      },
      scene
    );

    const innerPolygon = BABYLON.MeshBuilder.ExtrudePolygon(
      "innerPolygon",
      {
        shape: innerShape,
        depth: 0.2,
        sideOrientation: BABYLON.Mesh.DOUBLESIDE,
      },
      scene
    );

    const outerCSG = BABYLON.CSG.FromMesh(outerPolygon);
    const innerCSG = BABYLON.CSG.FromMesh(innerPolygon);
    const frameCSG = outerCSG.subtract(innerCSG);

    outerPolygon.dispose();
    innerPolygon.dispose();

    const frameMaterial = new BABYLON.StandardMaterial("frameMat", scene);
    frameMaterial.diffuseColor = new BABYLON.Color3(1, 1, 1);

    const frameMesh = frameCSG.toMesh("frameMesh", frameMaterial, scene);
    frameMesh.overrideMaterialSideOrientation = BABYLON.Mesh.DOUBLESIDE;
    frameMesh.rotation.x = -Math.PI / 2;
    frameMesh.position.y = scaleFactor;

    var rp = new BABYLON.ReflectionProbe("ref", 512, scene);
    rp.renderList.push(frameMesh);

    var pbr = new BABYLON.PBRMaterial("pbr", scene);
    pbr.reflectionTexture = rp.cubeTexture;
    frameMesh.material = pbr;
  }

  createExtrudeFrame();

  let rootMesh = null;

  BABYLON.SceneLoader.ImportMeshAsync(
    "",
    "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/",
    "black_panther_-_marvel_rivals_-_animated.glb"
  ).then((result) => {
    rootMesh = result.meshes[0];

    rootMesh.scaling.scaleInPlace(1.5);
    rootMesh.position = new BABYLON.Vector3(-0.15, -0.33, -0.27);
    rootMesh.rotation.y = BABYLON.Tools.ToRadians(349.2);

    rootMesh.getChildMeshes().forEach((m) => {
      m.renderingGroupId = 1;
    });

    const energyMesh = rootMesh.getChildMeshes(false, (m) => m.name === "Object_11")[0];
    if (energyMesh && energyMesh.material) {
      energyMesh.material.emissiveTexture = null;
      energyMesh.material.albedoColor = BABYLON.Color3.FromHexString("#4800F9").toLinearSpace();
      energyMesh.material.emissiveColor = BABYLON.Color3.FromHexString("#7803E9").toLinearSpace();
    }

    var defaultPipeline = new BABYLON.DefaultRenderingPipeline("DRPP", true, scene, [camera]);
    defaultPipeline.fxaaEnabled = true;
    defaultPipeline.samples = 4;
    defaultPipeline.imageProcessingEnabled = false;
    defaultPipeline.bloomEnabled = true;
    defaultPipeline.bloomThreshold = 0.07;
    defaultPipeline.bloomWeight = 0.55;
    defaultPipeline.bloomKernel = 57;
    defaultPipeline.bloomScale = 0.25;

    defaultPipeline.chromaticAberrationEnabled = true;

    let lastRandomTime = 0;
    let targetAlpha = camera.alpha;
    let targetBeta = camera.beta;

    scene.onBeforeRenderObservable.add(() => {
      const time = performance.now() * 0.001;
      const cycle = 5.0;
      const amount = Math.sin((time / cycle) * Math.PI * 2) * 15;
      defaultPipeline.chromaticAberration.aberrationAmount = amount;
    });

    scene.onBeforeRenderObservable.add(() => {
      const time = performance.now() * 0.001;
      const cycle = 3.5;
      if (time - lastRandomTime > cycle) {
        lastRandomTime = time;
        targetAlpha = BABYLON.Scalar.Clamp(
          camera.lowerAlphaLimit + Math.random() * (camera.upperAlphaLimit - camera.lowerAlphaLimit),
          camera.lowerAlphaLimit,
          camera.upperAlphaLimit
        );
        targetBeta = BABYLON.Scalar.Clamp(
          camera.lowerBetaLimit + Math.random() * (camera.upperBetaLimit - camera.lowerBetaLimit),
          camera.lowerBetaLimit,
          camera.upperBetaLimit
        );
      }

      camera.alpha = BABYLON.Scalar.Lerp(camera.alpha, targetAlpha, 0.02);
      camera.beta = BABYLON.Scalar.Lerp(camera.beta, targetBeta, 0.02);
    });
  });

  return scene;
}
